/// <summary>
/// Class contains the business logic for MetTransfer order shipment form
/// </summary>
public class MetTransferOrderShipmentForm
{
}

Method.Source:
    /// <summary>
    /// Transfers shipment to a load when button is clicked.
    /// </summary>
    /// <param name="_metTransferShipmentTable">
    /// Shipment to be transferred.
    /// </param>
    void Transfer_clicked(MetTransferShipmentTable  _metTransferShipmentTable)
    {
        Dialog dialog = new dialog("@WAX2969");
        dialog.formBuildDesign().dialogSize(DialogSize::Small);
        DialogField loadId = dialog.addField(extendedTypeStr(MetLoadId));

        loadId.registerOverrideMethod(identifierStr(lookup), methodStr(MetTransferOrderShipmentForm, loadIdDialogControl_Lookup), this);

        if (dialog.run())
        {
            _metTransferShipmentTable.transferShipment(loadId.value());
        }
    }

    /// <summary>
    /// Performs lookup for load id.
    /// </summary>
    /// <param name="_ctrl">
    /// Form control.
    /// </param>
    protected void loadIdDialogControl_Lookup(FormStringControl _ctrl)
    {
        SysTableLookup          sysTableLookup = SysTableLookup::newParameters(tableNum(MetTransferShipmentTable), _ctrl);
        Query                   query = new Query();
        QueryBuildDataSource    queryBuildDataSource = query.addDataSource(tableNum(MetTransferShipmentTable));

        //exclude Shipped and Received loads
        queryBuildDataSource.addRange(fieldNum(MetTransferShipmentTable, MetShipmentStatus)).value(strFmt("..%1", queryValue(MetShipmentStatus::Loaded)));

        sysTableLookup.addLookupfield(fieldNum(MetTransferShipmentTable, MetLoadId));
        //sysTableLookup.addLookupfield(fieldNum(WHSLoadTable, LoadStatus));

        sysTableLookup.parmQuery(query);
        sysTableLookup.performFormLookup();
    }

    /// <summary>
    /// 
    /// </summary>
    /// <param name = "MetTransferShipmentTable">The current shipment</param>
    /// <returns>true if the dialog could be successfully created; otherwise false.</returns>
    public boolean transferToNewLoad(MetTransferShipmentTable _metTransferShipmentTable)
    {
        boolean ret = false;
        NumberSeq                   numberSeqLoadId;
        MetLoadId                   newMetLoadID;

        Dialog dialog = new Dialog("@WAX309");
        var dialogMetLoadId = dialog.addField(extendedTypeStr(WHSLoadTemplateId));

        numberSeqLoadId = NumberSeq::newGetNum(WHSParameters::numRefMetLoadID());
        newMetLoadID       = numberSeqLoadId.num();
        dialogMetLoadId.value(newMetLoadID);

        dialog.run();
        if(dialog.closedOk())
        {
            _metTransferShipmentTable.transferShipment(dialogMetLoadId.value());
            ret = true;

        }

        return ret;
    }
